<?php $homeStats=[];$homeTestimonials=[];$homePeople=[];$homeArticles=[];try{$homeStats=one("SELECT (SELECT COUNT(*) FROM training_programs WHERE is_active=1) programs,(SELECT COUNT(*) FROM instructors WHERE is_published=1) instructors,(SELECT COUNT(*) FROM enrollments WHERE status='completed') completed");$homeTestimonials=rows('SELECT * FROM testimonials WHERE is_published=1 ORDER BY id DESC LIMIT 3');$homePeople=rows('SELECT id,name,expertise FROM instructors WHERE is_published=1 ORDER BY id DESC LIMIT 3');$homeArticles=rows('SELECT slug,title,category,excerpt FROM articles WHERE published_at<=NOW() ORDER BY published_at DESC LIMIT 3');}catch(Throwable $ex){error_log($ex->getMessage());} ?>
<section class="public-page" style="padding-top:60px;padding-bottom:60px"><div class="page-heading"><p class="eyebrow">JALUR BELAJAR ANDA</p><h2 class="section-title">Dari kebutuhan teknis ke pembelajaran terarah.</h2><p>Pilih bidang yang ingin dikembangkan, cek jadwal, lalu kelola kegiatan belajar melalui portal peserta.</p></div><div class="actions"><?php foreach(['Reliability','Equipment','Diagnostics','Academic'] as $category): ?><a class="btn secondary" href="programs.php?category=<?= e($category) ?>#catalog-search"><?= e($category) ?></a><?php endforeach; ?></div><div class="catalog-grid" style="margin-top:30px"><?php foreach([['01 / Daring','Belajar dari lokasi Anda','Materi digital dan sesi kelas langsung melalui tautan yang tersedia untuk peserta terdaftar.'],['02 / Tatap muka','Fokus pada praktik','Ikuti sesi di lokasi pelatihan dengan informasi persiapan dan catatan kehadiran.'],['03 / Hybrid','Terhubung di setiap tahap','Gabungkan persiapan mandiri, pertemuan langsung, tugas, dan evaluasi dalam satu portal.']] as [$tag,$title,$body]): ?><article class="panel"><span class="badge"><?= e($tag) ?></span><h2 style="margin-top:18px"><?= e($title) ?></h2><p class="muted"><?= e($body) ?></p></article><?php endforeach; ?></div><p class="muted" style="margin-top:18px">Ketersediaan metode mengikuti silabus dan jadwal resmi setiap program.</p><div class="portal-stats"><?php if($homeStats):foreach([['Program aktif',$homeStats['programs']],['Profil instruktur terbit',$homeStats['instructors']],['Pelatihan peserta selesai',$homeStats['completed']]] as [$label,$value]): ?><div class="stat"><strong><?= (int)$value ?></strong><span><?= e($label) ?></span></div><?php endforeach;endif; ?><a class="stat" href="auth.php?mode=register"><strong>Mulai</strong><span>Buat akun peserta</span></a></div><?php if($homePeople): ?><h2 class="section-title" style="margin-top:40px">Praktisi pengajar</h2><div class="portal-grid" style="margin-top:20px"><?php foreach($homePeople as $person): ?><a class="panel" href="instructors.php?id=<?= (int)$person['id'] ?>"><h3><?= e($person['name']) ?></h3><p class="muted"><?= e($person['expertise']) ?></p></a><?php endforeach; ?></div><?php endif; ?><h2 style="font-size:25px;font-weight:800;margin-top:40px">Pengalaman peserta</h2><?php if(!$homeTestimonials): ?><p class="muted" style="margin-top:12px">Testimoni peserta belum dipublikasikan.</p><?php else: ?><div class="catalog-grid" style="margin-top:20px"><?php foreach($homeTestimonials as $testimony): ?><blockquote class="panel"><p class="lesson-body"><?= e($testimony['quote']) ?></p><cite class="muted"><?= e($testimony['name'].' · '.$testimony['organization']) ?></cite></blockquote><?php endforeach; ?></div><?php endif; ?><?php if($homeArticles): ?><h2 class="section-title" style="margin-top:40px">Artikel terbaru</h2><div class="catalog-grid" style="margin-top:20px"><?php foreach($homeArticles as $article): ?><a class="panel" href="article.php?slug=<?= e($article['slug']) ?>"><span class="badge"><?= e($article['category']) ?></span><h3><?= e($article['title']) ?></h3><p class="muted"><?= e($article['excerpt']) ?></p></a><?php endforeach; ?></div><?php endif; ?><div class="actions"><a href="about.php" class="btn secondary">Tentang MIGAS & FAQ</a><a href="auth.php?mode=register" class="btn">Daftar akun peserta</a></div></section>
